import{_ as a,o as t,c as i,aA as o}from"./chunks/framework.D53uh-0L.js";const h=JSON.parse('{"title":"MTK_GMG Style","description":"","frontmatter":{},"headers":[],"relativePath":"man/example_mtk_gmg.md","filePath":"man/example_mtk_gmg.md","lastUpdated":null}'),r={name:"man/example_mtk_gmg.md"};function l(s,e,n,m,p,d){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="MTK_GMG-Style" tabindex="-1">MTK_GMG Style <a class="header-anchor" href="#MTK_GMG-Style" aria-label="Permalink to &quot;MTK_GMG Style {#MTK_GMG-Style}&quot;">​</a></h1><p>This set of examples demonstrates the MTK_GMG coding style: integrating MagmaThermoKinematics with <a href="https://github.com/JuliaGeodynamics/GeophysicalModelGenerator.jl" target="_blank" rel="noreferrer">GeophysicalModelGenerator</a> inputs and user-overridden runtime hooks.</p><p>This is a nice feature as it allows you to model natural magmatic systems, and take observables such as seismic tomography and the actual topography into account while constructing your model. The <code>GeophysicalModelGenerator</code> package allows you to even import screenshots from published papers and compare them with the modelling results. Likewise, you can use MTK output along with <a href="https://computationalthermodynamics.github.io/MAGEMin_C.jl/dev/" target="_blank" rel="noreferrer">MAGEMin</a> phase diagrams (and seismic velocities) to compute synthetic seismic tomography output from your simulation.</p><p>MTK is fully customisable, and allows you to inject a deeper magmatic system for some period of time, while later switching to shallower injections. Thanks to its integration with <a href="https://github.com/JuliaGeodynamics/GeoParams.jl" target="_blank" rel="noreferrer">GeoParams</a>, it is also straightforward to change the material parameters (and test the effect of temperature-dependent thermal conductivity vs. constant conductivity, for example). At the same time, your whole simulation is contained in a single file, which makes it highly reproducible and easy to share — as required by the FAIR data principles of many journals.</p><p>The Unzen and Lanin 3D examples show how different geological datasets and initialization workflows can be plugged into one consistent MTK_GMG simulation pipeline.</p><h2 id="Core-Pattern" tabindex="-1">Core Pattern <a class="header-anchor" href="#Core-Pattern" aria-label="Permalink to &quot;Core Pattern {#Core-Pattern}&quot;">​</a></h2><p>The general workflow is as follows:</p><ol><li><p>Initialize backend and MTK modules.</p></li><li><p>Optionally construct or import a CartData model using the <a href="https://github.com/JuliaGeodynamics/GeophysicalModelGenerator.jl" target="_blank" rel="noreferrer">GeophysicalModelGenerator</a>.</p></li><li><p>Override selected functions in the MTK_GMG namespace for custom output, visualization, initialization, or time-dependent diagnostics, or dike injection.</p></li><li><p>Define NumParam and DikeParam inputs.</p></li><li><p>Define material parameters as tuples of SetMaterialParams entries.</p></li><li><p>Run MTK_GeoParams_2D or MTK_GeoParams_3D.</p></li></ol><h2 id="Overriding-custom-settings" tabindex="-1">Overriding custom settings <a class="header-anchor" href="#Overriding-custom-settings" aria-label="Permalink to &quot;Overriding custom settings {#Overriding-custom-settings}&quot;">​</a></h2><p>The MTK_GMG style commonly overrides these functions:</p><ul><li><p>MTK_GMG.MTK_initialize!</p></li><li><p>MTK_GMG.MTK_visualize_output</p></li><li><p>MTK_GMG.MTK_print_output</p></li><li><p>MTK_GMG.MTK_update_TimeDepProps!</p></li></ul><h2 id="Dedicated-Examples" tabindex="-1">Dedicated Examples <a class="header-anchor" href="#Dedicated-Examples" aria-label="Permalink to &quot;Dedicated Examples {#Dedicated-Examples}&quot;">​</a></h2><p>The following examples illustrate how to use this workflow:</p><ul><li><p><a href="./example_mtk_gmg1">MTK_GMG Example 1</a></p></li><li><p><a href="./example_mtk_gmg2">MTK_GMG Example 2 (Unzen)</a></p></li><li><p><a href="./example_mtk_gmg_3d">MTK_GMG 3D Examples (Unzen3D, Lanin3D)</a></p></li></ul>',14)])])}const u=a(r,[["render",l]]);export{h as __pageData,u as default};
